//! AVR32DD20 register addresses and bitfield values, generated by `build.rs`
//! from the ATDF in `vendor/`. Its reset values are left out, since some
//! disagree with the datasheet.

include!(concat!(env!("OUT_DIR"), "/regs.rs"));

/// The ATDF gives `SAMPLEN` no named values. `2 + SAMPLEN` ADC clocks, 34 µs at 1 MHz
/// (DS40002413B §33.3.3.4); the temperature sensor wants at least 28 µs (§33.3.3.8).
pub const ADC_SAMPLEN_32CLK: u8 = 32;

const _: () = assert!(ADC_SAMPLEN == u8::MAX);
